--sk-back-to-top-bg.default:
var(--sk-button-bg, light-dark(
      color-mix(in oklab, var(--color-bg-surface-sunken) 60%, transparent),
      color-mix(in oklab, var(--color-action-neutral) 42%, transparent)
    ))

--sk-media-overlay-shade-ink.default:
color-mix(
      in oklch,
      var(--sk-media-overlay-shade-base) var(--sk-media-overlay-shade-opacity),
      transparent
    )

--sk-media-overlay-shade-tint-edge.default:
color-mix(
      in oklch,
      var(--sk-media-overlay-shade-tint) calc(var(--sk-media-overlay-shade-mix) * 1.1),
      transparent
    )

--sk-media-overlay-shade-tint-mid.default:
color-mix(
      in oklch,
      var(--sk-media-overlay-shade-tint) calc(var(--sk-media-overlay-shade-mix) * 0.55),
      transparent
    )

--sk-rating-off-color.default:
light-dark(
      color-mix(in oklab, var(--color-border-default) 50%, transparent),
      var(--color-border-default)
    )

--sk-slider-track.default:
light-dark(
      var(--color-bg-surface-sunken),
      color-mix(in oklab, var(--color-text-primary) 24%, var(--color-bg-surface))
    )
